from itertools import product
import sys
sys.setrecursionlimit(1 << 20)

N, H, W = map(int, input().split())
AB = [list(map(int, input().split())) for _ in range(N)]
global ans
ans = False

def dfs(x, y, rem, masu):
    global ans
    if all(all(row) for row in masu):
        ans = True
        return True
    if y == W:
        x += 1
        y = 0
    if x == H:
        return False
    if masu[x][y]:
        return dfs(x, y + 1, rem, masu)

    for i in range(len(rem)):
        a, b = rem[i]
        for h, w in [(a, b), (b, a)]:
            if x + h <= H and y + w <= W:
                can_place = True
                for dx in range(h):
                    for dy in range(w):
                        if masu[x + dx][y + dy]:
                            can_place = False
                            break
                    if not can_place:
                        break
                if can_place:
                    for dx in range(h):
                        for dy in range(w):
                            masu[x + dx][y + dy] = True
                    if dfs(x, y + w, rem[:i] + rem[i+1:], masu):
                        return True
                    for dx in range(h):
                        for dy in range(w):
                            masu[x + dx][y + dy] = False
    return False

for bits in product([0, 1], repeat=N):
    item = [AB[i] for i in range(N) if bits[i]]
    masu = [[False] * W for _ in range(H)]
    if sum(a * b for a, b in item) == H * W:
        if dfs(0, 0, item, masu):
            ans = True
            break

print("Yes" if ans else "No")
